func TestReproUnbufferedDeadlock(t *testing.T) {
	ch := make(chan Image)
	done := make(chan struct{})
	go func() { ch <- Image{}; close(done) }()
	select {
	case <-done: t.Fatal("should have blocked")
	case <-time.After(200 * time.Millisecond):
		t.Log("unbuffered channel deadlock confirmed")
	}
}
